from cerebrum.core.simulation_engine import SimulationModel

class FinancialRiskModel(SimulationModel):
    def run_simulation(self, input_data: Dict[str, Any]) -> Dict[str, Any]:
        amount = input_data.get("amount", 0)
        user_role = input_data.get("user_role", "standard")
        
        risk_score = 0
        if amount > 10000:
            risk_score += 80
        if user_role == "admin":
            risk_score += 30
        
        return {
            "risk_score": risk_score,
            "recommendation": "approve" if risk_score < 70 else "review"
        }

