import pytest
from cerebrum.core.simulation_engine import SimulationEngine, SimulationModel
from cerebrum.models.financial_risk_model import FinancialRiskModel

def test_engine_initialization():
    engine = SimulationEngine()
    assert isinstance(engine, SimulationEngine)

def test_model_registration_and_execution():
    engine = SimulationEngine()
    engine.register_model("financial_risk", FinancialRiskModel)
    
    input_data = {"amount": 15000, "user_role": "admin"}
    result = engine.execute_simulation("financial_risk", input_data)
    
    assert result["risk_score"] == 110
    assert result["recommendation"] == "review"

def test_unknown_model():
    engine = SimulationEngine()
    with pytest.raises(ValueError):
        engine.execute_simulation("nonexistent_model", {})

def test_edge_cases():
    engine = SimulationEngine()
    engine.register_model("financial_risk", FinancialRiskModel)
    
    # Test zero amount
    result = engine.execute_simulation("financial_risk", {"amount": 0, "user_role": "standard"})
    assert result["risk_score"] == 0
    assert result["recommendation"] == "approve"
    
    # Test amount just above threshold
    result = engine.execute_simulation("financial_risk", {"amount": 10001, "user_role": "standard"})
    assert result["risk_score"] == 80
    assert result["recommendation"] == "review"

